def strategy(history, rng):
    n = len(history)
    if n == 0 or n == 1:
        return 'C'
    if n >= 99:
        return 'D'
    last_my, last_opp = history[-1]
    total_my_d = 0
    total_opp_d = 0
    for m, o in history:
        if m == 'D':
            total_my_d += 1
        if o == 'D':
            total_opp_d += 1
    if total_opp_d == 0:
        if n >= 5:
            if total_my_d == 0:
                return 'D'
            if total_my_d == 1 and last_my == 'D':
                return 'C'
            return 'D'
        return 'C'
    recent_len = 8 if n >= 8 else n
    recent_opp_d = 0
    for m, o in history[-recent_len:]:
        if o == 'D':
            recent_opp_d += 1
    recent_coop = recent_len - recent_opp_d
    prev_c = 0
    prev_d = 0
    resp_c = 0
    resp_d = 0
    for i in range(1, n):
        pm = history[i - 1][0]
        if pm == 'C':
            prev_c += 1
            if history[i][1] == 'D':
                resp_c += 1
        else:
            prev_d += 1
            if history[i][1] == 'D':
                resp_d += 1
    unprov_low = prev_c == 0 or resp_c * 100 <= prev_c * 15
    punish_low = prev_d == 0 or resp_d * 100 <= prev_d * 30
    punish_bad = prev_d > 0 and resp_d * 10 >= prev_d * 6
    if total_opp_d == n:
        return 'D'
    if recent_len >= 6 and recent_opp_d >= recent_len - 1 and total_opp_d * 10 >= n * 7:
        return 'D'
    if total_opp_d * 10 >= n * 7 and recent_opp_d >= 4:
        return 'D'
    if last_opp == 'D':
        if recent_opp_d >= 3 or total_opp_d * 10 >= n * 4:
            return 'D'
        if last_my == 'C':
            if n >= 2 and history[-2][0] == 'D':
                if unprov_low and punish_low:
                    return 'C'
                if recent_opp_d <= 1 and total_opp_d <= max(3, n // 5):
                    return 'C'
                return 'D'
            if total_opp_d <= 1 and n >= 20 and unprov_low:
                return 'C'
            return 'D'
        if recent_opp_d <= 1 and unprov_low and total_opp_d <= max(3, n // 5):
            return 'C'
        if total_my_d > 0 and punish_bad and recent_opp_d <= 2 and unprov_low:
            return 'C'
        return 'D'
    if total_my_d > total_opp_d + 3 and recent_opp_d <= 1 and unprov_low and n >= 12:
        return 'D'
    if total_my_d > 0 and punish_low and unprov_low and recent_opp_d <= 1:
        if total_opp_d <= max(2, n // 10):
            if total_my_d == 1 and last_my == 'D' and total_opp_d > 0:
                if n >= 80:
                    return 'D'
                if rng is not None and rng.random() < 0.15:
                    return 'D'
                return 'C'
            if prev_d > 0 and resp_d == 0 and recent_coop == recent_len and total_opp_d <= 1:
                if n >= 20:
                    return 'D'
            if n >= 10 and recent_coop >= recent_len - 1:
                if rng is not None and rng.random() < 0.25:
                    return 'D'
            if n >= 50:
                if rng is not None and rng.random() < 0.2:
                    return 'D'
    if recent_opp_d == 0 and total_opp_d <= 2 and unprov_low and punish_low:
        if n >= 70:
            if rng is not None and rng.random() < 0.3:
                return 'D'
    return 'C'
